/**
 * Expo config plugin: signs Android release builds with the keystore in /credentials
 * (android/ is regenerated by `expo prebuild`, so signing must be applied here, not by hand).
 *
 * credentials/keystore.properties:
 *   storeFile=../../credentials/autobiz-release.jks   (relative to android/app)
 *   storePassword=…  keyAlias=…  keyPassword=…
 * If the file is missing, release builds fall back to the debug key (local testing only).
 */
const { withAppBuildGradle, withGradleProperties } = require("expo/config-plugins");

const LOADER = `
// [withReleaseSigning] load release keystore credentials
def abKeystoreProps = new Properties()
def abKeystoreFile = rootProject.file("../credentials/keystore.properties")
if (abKeystoreFile.exists()) { abKeystoreFile.withInputStream { abKeystoreProps.load(it) } }
`;

const RELEASE_SIGNING = `
        release {
            if (abKeystoreFile.exists()) {
                storeFile file(abKeystoreProps["storeFile"])
                storePassword abKeystoreProps["storePassword"]
                keyAlias abKeystoreProps["keyAlias"]
                keyPassword abKeystoreProps["keyPassword"]
            }
        }`;

function withSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let g = cfg.modResults.contents;
    if (g.includes("[withReleaseSigning]")) return cfg;
    // 1. load properties before the android { } block
    g = g.replace(/\nandroid\s*\{/, `${LOADER}\nandroid {`);
    // 2. add a release signing config after the debug one
    g = g.replace(/(signingConfigs\s*\{\s*debug\s*\{[^}]*\})/, `$1${RELEASE_SIGNING}`);
    // 3. use it for the release build type
    g = g.replace(
      /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig\s+signingConfigs\.debug/,
      `$1signingConfig abKeystoreFile.exists() ? signingConfigs.release : signingConfigs.debug`
    );
    if (!g.includes("signingConfigs.release")) throw new Error("[withReleaseSigning] could not patch app/build.gradle");
    cfg.modResults.contents = g;
    return cfg;
  });
}

function withArmOnly(config) {
  return withGradleProperties(config, (cfg) => {
    cfg.modResults = cfg.modResults.filter((p) => !(p.type === "property" && p.key === "reactNativeArchitectures"));
    cfg.modResults.push({ type: "property", key: "reactNativeArchitectures", value: "armeabi-v7a,arm64-v8a" });
    return cfg;
  });
}

module.exports = (config) => withArmOnly(withSigning(config));
